import{_ as t,o,c as n,j as e,a as r}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/107-正确提问带给人的不快.md","filePath":"books/xuehui-tiwen/107-正确提问带给人的不快.md","lastUpdated":1794316978000}'),s={name:"books/xuehui-tiwen/107-正确提问带给人的不快.md"};function _(i,a,l,d,c,p){return o(),n("div",null,[...a[0]||(a[0]=[e("h2",{id:"正确提问带给人的不快",tabindex:"-1"},[r("正确提问带给人的不快 "),e("a",{class:"header-anchor",href:"#正确提问带给人的不快","aria-label":'Permalink to "正确提问带给人的不快"'},"​")],-1),e("p",null,"第1章里提到过，批判性思维是一项社交活动。想和别人打成一片，我们首先要愿意提出一些正确的问题，以便了解其他人的看法。一定要记住，并不是每个人都乐于见到自己的论证被质疑。所以第一个障碍就是，你提出正确的问题可能使他人产生的不适。",-1),e("p",null,"作为被提问对象，被人不断提出批判性的问题，可能会让人感觉自己好像站在法庭的证人席上接受盘问。随着提出的问题不断增多，被提问对象可能会渐渐感到不快，甚至会觉得自己受到了威胁，结果就是他可能发脾气，甚至不愿再继续交谈。他可能不习惯于解释支持其论点的各种理由，或者他为什么要坚持那些理由。虽然你认为提出这些问题对你和其他谨慎思考者而言是必不可少的步骤，但这并不意味着被提问者也觉得有这个必要。",-1),e("p",null,"我们得时刻注意所提的问题给被提问者带来了怎样的影响。批判性思维者如果不够小心谨慎，就有可能会因为给周围的人带来不必要的不快而伤感情、失去朋友。所以，为了维系社会关系，我们必须要了解自己的谈话对象，在使用批判性思维的时候注重策略。",-1)])])}const f=t(s,[["render",_]]);export{m as __pageData,f as default};
